mapper.select:
SELECT package_id, package_no, material_name, specification, batch_no, expiry_date, package_quantity, unit_quantity, total_quantity, warehouse_name, status, create_user_name, create_time FROM spd_bulk_package WHERE del_flag = 0
AND package_no LIKE CONCAT('%', #{query.packageNo}, '%')
AND material_name LIKE CONCAT('%', #{query.materialName}, '%')
AND batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND status = #{query.status}
AND create_time >= #{query.startTime}
AND create_time <= #{query.endTime}
ORDER BY create_time DESC
